import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  spring,
  interpolate,
  Img,
  staticFile,
} from "remotion";
import { TransitionSeries, linearTiming } from "@remotion/transitions";
import { fade } from "@remotion/transitions/fade";
import {
  SPRINGS,
  TIMING,
  springIn,
  staggeredSpring,
  ambientDrift,
  compoundReveal,
  inOutEnvelope,
} from "../motion";

// ============================================================
// THEME
// ============================================================
const COLORS = {
  bg: "#161718",
  card: "#1d1e1f",
  border: "#3d3f43",
  text: "#f4f4f5",
  textMuted: "#bfc1c5",
  textSubtle: "#8c93a8",
  orange: "#F86606",
  orangeDeep: "#FF4800",
  orangeTint: "rgba(248,102,6,0.16)",
};

const FONT_MARKETING = "'GT Walsheim', Inter, sans-serif";
const FONT_PRIMARY = "Inter, sans-serif";
const FONT_MONO = "'JetBrains Mono', monospace";

export const fps = 25;
const TRANSITION = 8;

// ============================================================
// BACKGROUND — empty so "No Background" export is clean
// ============================================================
const Background: React.FC = () => <AbsoluteFill />;

// ============================================================
// SCENE 1 — Three of nine channels tripled their ratio
// ============================================================
const SceneNineGridToTriple: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps: vfps } = useVideoConfig();

  const phaseA = interpolate(frame, [55, 75], [1, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const phaseB = interpolate(frame, [55, 75], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const highlightedIndices = [1, 4, 7];
  const cells = Array.from({ length: 9 });
  const gridIn = springIn(frame, vfps, 4, "LIQUID");

  return (
    <AbsoluteFill style={{ fontFamily: FONT_PRIMARY }}>
      <Background />

      {/* PHASE A: 9-grid */}
      <div
        style={{
          position: "absolute",
          left: "50%",
          top: "50%",
          transform: `translate(-50%, -50%) scale(${interpolate(phaseA, [0, 1], [0.85, 1])})`,
          display: "grid",
          gridTemplateColumns: "repeat(3, 1fr)",
          gap: 60,
          opacity: gridIn * phaseA,
          pointerEvents: phaseA < 0.1 ? "none" : "auto",
        }}
      >
        {cells.map((_, i) => {
          const isHighlight = highlightedIndices.includes(i);
          const cellIn = staggeredSpring(frame, vfps, i, 10, 5, "ELASTIC");
          const pulseDelay = isHighlight
            ? 30 + highlightedIndices.indexOf(i) * 8
            : 0;
          const pulseP = isHighlight
            ? springIn(frame, vfps, pulseDelay, "LIQUID")
            : 0;
          const driftY = ambientDrift(frame, 4, 110 + i * 13, `cell-${i}`);
          const driftR = ambientDrift(frame, 1.2, 140 + i * 9, `cell-r-${i}`);

          return (
            <div
              key={i}
              style={{
                width: 380,
                height: 250,
                borderRadius: 24,
                background: isHighlight
                  ? COLORS.orange
                  : "rgba(255,255,255,0.18)",
                border: isHighlight
                  ? `2px solid ${COLORS.orange}`
                  : `1px solid ${COLORS.border}`,
                opacity: cellIn,
                transform: `translateY(${interpolate(cellIn, [0, 1], [40, 0]) + driftY}px) scale(${interpolate(cellIn, [0, 1], [0.85, 1]) + pulseP * 0.04}) rotate(${driftR * 0.3}deg)`,
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                position: "relative",
                overflow: "hidden",
              }}
            >
              <div
                style={{
                  width: 0,
                  height: 0,
                  borderLeft: `${isHighlight ? 64 : 48}px solid ${isHighlight ? "#fff" : COLORS.textSubtle}`,
                  borderTop: `${isHighlight ? 38 : 28}px solid transparent`,
                  borderBottom: `${isHighlight ? 38 : 28}px solid transparent`,
                  marginLeft: 16,
                }}
              />
              {isHighlight && (
                <div
                  style={{
                    position: "absolute",
                    top: 24,
                    right: 24,
                    fontSize: 64,
                    color: "#fff",
                    fontWeight: 800,
                    fontFamily: FONT_MARKETING,
                    opacity: pulseP,
                    transform: `translateY(${interpolate(pulseP, [0, 1], [20, 0])}px)`,
                  }}
                >
                  ↑
                </div>
              )}
            </div>
          );
        })}
      </div>

      {/* PHASE B: Three growing bar charts */}
      <div
        style={{
          position: "absolute",
          left: "50%",
          top: "50%",
          transform: `translate(-50%, -50%) scale(${interpolate(phaseB, [0, 1], [0.92, 1])})`,
          display: "flex",
          gap: 120,
          alignItems: "flex-end",
          opacity: phaseB,
          pointerEvents: phaseB < 0.1 ? "none" : "auto",
        }}
      >
        {[0, 1, 2].map((channelIdx) => {
          const baseDelay = 70 + channelIdx * 8;
          const growP = springIn(frame, vfps, baseDelay, "LIQUID");
          const tripleP = springIn(frame, vfps, baseDelay + 30, "LIQUID");
          const driftY = ambientDrift(
            frame,
            3,
            90 + channelIdx * 20,
            `bar-${channelIdx}`
          );

          const bars = [
            { h: 120, label: "before" },
            { h: 200, label: "mid" },
            { h: 380, label: "after" },
          ];

          return (
            <div
              key={channelIdx}
              style={{
                display: "flex",
                flexDirection: "column",
                alignItems: "center",
                gap: 32,
                opacity: growP,
                transform: `translateY(${driftY}px)`,
              }}
            >
              <div
                style={{
                  width: 90,
                  height: 90,
                  borderRadius: "50%",
                  background: "rgba(255,255,255,0.18)",
                  border: `2px solid ${COLORS.orange}`,
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                }}
              >
                <div
                  style={{
                    width: 0,
                    height: 0,
                    borderLeft: `26px solid ${COLORS.orange}`,
                    borderTop: `16px solid transparent`,
                    borderBottom: `16px solid transparent`,
                    marginLeft: 8,
                  }}
                />
              </div>

              <div
                style={{
                  display: "flex",
                  gap: 18,
                  alignItems: "flex-end",
                  height: 420,
                }}
              >
                {bars.map((bar, bi) => {
                  const barDelay = baseDelay + 8 + bi * 8;
                  const barP = springIn(frame, vfps, barDelay, "LIQUID");
                  const isTriple = bi === 2;
                  const finalH = bar.h * interpolate(barP, [0, 1], [0.05, 1]);
                  const tripleScale = isTriple
                    ? interpolate(tripleP, [0, 1], [1, 1.05])
                    : 1;

                  return (
                    <div
                      key={bi}
                      style={{
                        width: 64,
                        height: finalH,
                        background: isTriple
                          ? COLORS.orange
                          : "rgba(255,255,255,0.35)",
                        borderRadius: 8,
                        transformOrigin: "bottom",
                        transform: `scaleY(${tripleScale})`,
                      }}
                    />
                  );
                })}
              </div>

              <div
                style={{
                  background: COLORS.orange,
                  border: `1.5px solid ${COLORS.orange}`,
                  borderRadius: 999,
                  padding: "12px 28px",
                  fontSize: 42,
                  fontWeight: 700,
                  fontFamily: FONT_MARKETING,
                  color: "#fff",
                  letterSpacing: "-0.01em",
                  opacity: tripleP,
                  transform: `translateY(${interpolate(tripleP, [0, 1], [16, 0])}px) scale(${interpolate(tripleP, [0, 1], [0.7, 1])})`,
                }}
              >
                ×3
              </div>
            </div>
          );
        })}
      </div>
    </AbsoluteFill>
  );
};

