      <div
        style={{
          position: "absolute",
          left: "50%",
          top: "50%",
          transform: `translate(-50%, -50%) scale(${inP})`,
          opacity: inP,
          width: 480,
          height: 480,
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
        }}
      >
        {[0, 1, 2].map((i) => {
          const ringP = (ringPulse + i * 0.33) % 1;
          return (
            <div
              key={i}
              style={{
                position: "absolute",
                width: 480,
                height: 480,
                borderRadius: "50%",
                border: `2px solid ${COLORS.orange}`,
                opacity: (1 - ringP) * 0.6,
                transform: `scale(${0.6 + ringP * 0.5})`,
              }}
            />
          );
